CREATE OR REPLACE FUNCTION public.vacleaner_admin_detach_booking_promo(p_booking_id uuid, p_extras jsonb, p_base_amount integer, p_total_amount integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_redemption public.vacleaner_promo_redemptions%rowtype;
  v_code public.vacleaner_promo_codes%rowtype;
begin
  perform 1 from public.vacleaner_bookings where id = p_booking_id for update;
  if not found then raise exception 'booking_not_found'; end if;

  select * into v_redemption
  from public.vacleaner_promo_redemptions
  where booking_id = p_booking_id
  order by created_at desc
  limit 1
  for update;

  perform set_config('vacleaner.allow_promo_detach','1',true);

  update public.vacleaner_bookings
  set extras = p_extras,
      base_amount = greatest(0, p_base_amount),
      total_amount = greatest(0, p_total_amount),
      updated_at = now()
  where id = p_booking_id;

  if v_redemption.id is not null then
    delete from public.vacleaner_promo_redemptions where id = v_redemption.id;
    select * into v_code from public.vacleaner_promo_codes where id = v_redemption.promo_code_id for update;
    if v_code.id is not null and v_code.activated_at is null then
      update public.vacleaner_promo_codes
      set active = false,
          expires_at = null,
          activation_source = null,
          activation_dispatch_id = null,
          activated_by = null
      where id = v_code.id;
    end if;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.vacleaner_admin_set_booking_referral(p_booking_id uuid, p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_booking public.vacleaner_bookings%rowtype;
  v_owner public.vacleaner_referral_codes%rowtype;
  v_use public.vacleaner_referral_uses%rowtype;
  v_extras jsonb;
  v_existing text;
  v_code text;
  v_raw integer;
  v_percent integer;
  v_loyalty integer;
  v_friend integer;
  v_amount integer;
  v_source text;
  v_type text;
  v_promo jsonb;
  v_friend_meta jsonb;
  v_discount jsonb;
  v_updated public.vacleaner_bookings%rowtype;
begin
  select * into v_booking from public.vacleaner_bookings
  where id=p_booking_id for update;
  if not found then raise exception 'invalid_booking'; end if;
  if v_booking.status not in ('pending','waiting_payment','confirmed') then
    raise exception 'invalid_transition';
  end if;

  v_extras := coalesce(v_booking.extras,'{}'::jsonb);
  v_existing := upper(coalesce(v_extras->'referral_friend'->>'code',''));
  v_code := upper(btrim(coalesce(p_code,'')));
  if v_code<>'' and v_code !~ '^VA-[A-Z0-9]{6,12}$' then
    raise exception 'invalid_referral';
  end if;

  select * into v_use from public.vacleaner_referral_uses
  where booking_id=p_booking_id for update;
  if found and v_use.status='completed' then
    raise exception 'referral_completed_locked';
  end if;
  if v_use.id is not null and v_use.status='pending'
     and v_existing<>'' and v_existing<>upper(v_use.referral_code) then
    raise exception 'referral_state_conflict';
  end if;
  if v_existing=v_code and ((v_code='' and v_use.id is null) or
      (v_code<>'' and v_use.status='pending' and upper(v_use.referral_code)=v_code)) then
    return jsonb_build_object('booking_id',v_booking.id,'changed',false,'code',nullif(v_code,''));
  end if;

  if coalesce(v_extras->'promo','null'::jsonb)<>'null'::jsonb and (
    v_existing='' or
    coalesce(v_extras->'promo'->>'campaign_type','') <> 'referral'
  ) then
    raise exception 'referral_existing_promo';
  end if;
  if coalesce(v_extras->'manual_discount'->>'type','none')<>'none' or
     coalesce(v_extras->'discount'->>'primary_source',v_extras->'discount'->>'source','none')='manual' then
    raise exception 'referral_existing_discount';
  end if;
  if coalesce(v_extras->'referral_reward'->>'applied','false')='true' then
    raise exception 'referral_existing_reward';
  end if;
  if exists(select 1 from public.vacleaner_promo_redemptions where booking_id=p_booking_id) then
    raise exception 'referral_existing_promo';
  end if;

  v_raw := greatest(0,coalesce(
    (v_extras->>'base_before_discount')::integer,
    v_booking.base_amount + coalesce((v_extras->'discount'->>'amount')::integer,0)
  ));
  v_percent := coalesce((v_extras->'loyalty'->>'percent')::integer,0);
  if v_percent not in (0,5,10) then v_percent:=0; end if;
  v_loyalty := least(v_raw,round(v_raw*v_percent/100.0)::integer);
  v_friend := least(v_raw,100);

  if v_code<>'' then
    select * into v_owner from public.vacleaner_referral_codes
    where upper(code)=v_code and active=true for share;
    if not found then raise exception 'referral_inactive'; end if;
    if v_owner.owner_phone=v_booking.customer_phone then
      raise exception 'self_referral';
    end if;
    if exists (
      select 1 from public.vacleaner_bookings b
      where b.customer_phone=v_booking.customer_phone and b.id<>p_booking_id
        and b.status in ('pending','waiting_payment','confirmed','issued','completed')
    ) then raise exception 'referral_first_rental_only'; end if;
    if exists (
      select 1 from public.vacleaner_referral_uses u
      where u.referred_phone=v_booking.customer_phone and u.booking_id<>p_booking_id
        and u.status in ('pending','completed')
    ) then raise exception 'referral_already_used'; end if;
    v_friend_meta:=jsonb_build_object(
      'code',v_owner.code,'referrer_phone',v_owner.owner_phone,'discount_amount',100);
  else
    v_friend_meta:='null'::jsonb;
  end if;

  if v_code<>'' and v_friend>v_loyalty then
    v_amount:=v_friend; v_source:='promo'; v_type:='fixed';
    v_promo:=jsonb_build_object(
      'code',v_owner.code,'campaign_id','','campaign_name','Приведи друга',
      'campaign_type','referral','kind','referral_friend',
      'referrer_phone',v_owner.owner_phone,
      'discount_type','fixed','discount_value',100,'applied',true);
  else
    v_amount:=v_loyalty;
    v_source:=case when v_loyalty>0 then 'loyalty' else 'none' end;
    v_type:=case when v_loyalty>0 then 'percent' else 'none' end;
    v_promo:='null'::jsonb;
  end if;
  v_discount:=jsonb_build_object(
    'type',v_type,'percent',case when v_source='loyalty' then v_percent else 0 end,
    'amount',v_amount,'source',v_source,'primary_source',v_source,
    'loyalty_amount',v_loyalty,'referral_reward_amount',0,'reason','');

  -- Must atomically update both the relationship and the booking totals.
  -- Skip the legacy promo-preservation trigger only within this transaction.
  perform pg_catalog.set_config('vacleaner.allow_promo_detach','1',true);
  if v_code='' then
    if v_use.id is not null and v_use.status='pending' then
      update public.vacleaner_referral_uses set status='cancelled',
        cancelled_at=now() where id=v_use.id;
    end if;
  elsif v_use.id is not null then
    if v_use.status not in ('pending','cancelled') then
      raise exception 'referral_completed_locked';
    end if;
    update public.vacleaner_referral_uses set
      referral_code=v_owner.code, referrer_phone=v_owner.owner_phone,
      referred_phone=v_booking.customer_phone, friend_discount_amount=100,
      status='pending', cancelled_at=null, completed_at=null
    where id=v_use.id;
  else
    insert into public.vacleaner_referral_uses(
      referral_code,referrer_phone,referred_phone,booking_id,friend_discount_amount,status
    ) values (
      v_owner.code,v_owner.owner_phone,v_booking.customer_phone,p_booking_id,100,'pending'
    );
  end if;

  update public.vacleaner_bookings set
    extras=v_extras || jsonb_build_object(
      'referral_friend',v_friend_meta,'promo',v_promo,
      'discount',v_discount,'base_before_discount',v_raw),
    base_amount=greatest(0,v_raw-v_amount),
    -- Preserve all already recorded non-rental charges (chemistry, manual + грн,
    -- delivery and extras). Only the rental-discount delta can change total_amount.
    total_amount=greatest(0,v_booking.total_amount +
      (greatest(0,v_raw-v_amount) - v_booking.base_amount)),
    updated_at=now()
  where id=p_booking_id
  returning * into v_updated;

  return jsonb_build_object('booking_id',v_updated.id,
    'changed',true,'code',nullif(v_code,''),
    'discount_amount',v_amount,'total_amount',v_updated.total_amount);
exception
  when unique_violation then raise exception 'referral_already_used';
end;
$function$

CREATE OR REPLACE FUNCTION public.vacleaner_apply_reservation(p_booking_id uuid, p_start_date date, p_return_date date, p_pickup_window text, p_return_window text, p_start_at timestamp with time zone, p_end_at timestamp with time zone, p_rental_days integer, p_resources jsonb, p_target_status text, p_hold_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS vacleaner_bookings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_booking public.vacleaner_bookings%rowtype;
  v_start_slot bigint;
  v_end_slot bigint;
  v_resource record;
  v_capacity integer;
  v_reserved integer;
  v_slot bigint;
  v_now timestamptz := pg_catalog.now();
begin
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext('vacleaner-slot-reservation-v1'));

  select * into v_booking
    from public.vacleaner_bookings
   where id = p_booking_id
   for update;
  if not found then raise exception 'booking_not_found'; end if;

  if p_target_status not in ('pending','waiting_payment','confirmed','issued') then
    raise exception 'invalid_target_status';
  end if;
  if p_pickup_window not in ('morning','evening') or p_return_window not in ('morning','evening') then
    raise exception 'invalid_window';
  end if;
  if p_return_date < p_start_date or p_rental_days < 1 or p_rental_days > 14 or p_end_at <= p_start_at then
    raise exception 'invalid_rental_period';
  end if;
  if p_resources is null or jsonb_typeof(p_resources) <> 'array' or jsonb_array_length(p_resources) < 1 then
    raise exception 'invalid_resources';
  end if;
  if p_target_status = 'waiting_payment' and p_hold_expires_at is null then
    raise exception 'invalid_hold';
  end if;

  v_start_slot := public.vacleaner_slot_index(p_start_date, p_pickup_window);
  v_end_slot := public.vacleaner_slot_index(p_return_date, p_return_window);
  if v_start_slot is null or v_end_slot is null or v_end_slot <= v_start_slot then
    raise exception 'invalid_rental_period';
  end if;

  if p_target_status <> 'pending' then
    for v_resource in
      select r.resource_code, sum(r.quantity)::integer as quantity
        from jsonb_to_recordset(p_resources) as r(resource_code text, quantity integer)
       where r.resource_code is not null and r.quantity > 0
       group by r.resource_code
    loop
      select i.capacity into v_capacity
        from public.vacleaner_inventory i
       where i.resource_code = v_resource.resource_code
         and i.active = true
       for share;
      if v_capacity is null then raise exception 'inventory_missing:%', v_resource.resource_code; end if;

      for v_slot in select * from pg_catalog.generate_series(v_start_slot, v_end_slot - 1)
      loop
        select coalesce(sum(br.quantity),0)::integer
          into v_reserved
          from public.vacleaner_booking_resources br
          join public.vacleaner_bookings b on b.id = br.booking_id
         where br.resource_code = v_resource.resource_code
           and b.id <> p_booking_id
           and (
             b.status in ('confirmed','issued')
             or (b.status = 'waiting_payment' and b.hold_expires_at > v_now)
           )
           and public.vacleaner_slot_index(b.start_date,b.pickup_window) <= v_slot
           and public.vacleaner_slot_index(b.return_date,b.return_window) > v_slot;

        if v_reserved + v_resource.quantity > v_capacity then
          raise exception 'inventory_conflict:%:%', v_resource.resource_code, v_slot;
        end if;
      end loop;
    end loop;
  end if;

  update public.vacleaner_bookings
     set start_date = p_start_date,
         return_date = p_return_date,
         pickup_window = p_pickup_window,
         return_window = p_return_window,
         start_at = p_start_at,
         end_at = p_end_at,
         rental_days = p_rental_days,
         status = p_target_status,
         hold_expires_at = case when p_target_status = 'waiting_payment' then p_hold_expires_at else null end,
         prepayment_paid = case when p_target_status = 'confirmed' then true else prepayment_paid end,
         prepayment_paid_at = case when p_target_status = 'confirmed' then coalesce(prepayment_paid_at,v_now) else prepayment_paid_at end,
         confirmed_at = case when p_target_status = 'confirmed' then coalesce(confirmed_at,v_now) else confirmed_at end,
         issued_at = case when p_target_status = 'issued' then coalesce(issued_at,v_now) else issued_at end,
         updated_at = v_now
   where id = p_booking_id
   returning * into v_booking;

  delete from public.vacleaner_booking_resources where booking_id = p_booking_id;
  insert into public.vacleaner_booking_resources(booking_id,resource_code,quantity)
  select p_booking_id, r.resource_code, sum(r.quantity)::integer
    from jsonb_to_recordset(p_resources) as r(resource_code text, quantity integer)
   where r.resource_code is not null and r.quantity > 0
   group by r.resource_code;

  return v_booking;
end;
$function$

CREATE OR REPLACE FUNCTION public.vacleaner_block_public_admin_bundle_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.product_code = 'puzzi_jimmy_abir' and new.source = 'vacleaner_website' then
    raise exception 'admin_only_product' using errcode = 'P0001';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.vacleaner_claim_notification_dispatch(p_event_key text, p_booking_id uuid, p_event_type text, p_lease_seconds integer DEFAULT 120)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  touched integer := 0;
  safe_lease integer := greatest(30, least(coalesce(p_lease_seconds, 120), 600));
begin
  if coalesce(btrim(p_event_key), '') = '' or length(p_event_key) > 180 then
    return false;
  end if;
  insert into public.vacleaner_notification_dispatch_claims(event_key, booking_id, event_type, locked_until, delivered_at, updated_at)
  values (p_event_key, p_booking_id, left(coalesce(p_event_type, 'unknown'), 40), now() + make_interval(secs => safe_lease), null, now())
  on conflict (event_key) do update
    set booking_id = excluded.booking_id,
        event_type = excluded.event_type,
        locked_until = excluded.locked_until,
        updated_at = now()
    where vacleaner_notification_dispatch_claims.delivered_at is null
      and vacleaner_notification_dispatch_claims.locked_until <= now();
  get diagnostics touched = row_count;
  return touched > 0;
end;
$function$

CREATE OR REPLACE FUNCTION public.vacleaner_confirm_booking(p_booking_id uuid)
 RETURNS vacleaner_bookings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_booking public.vacleaner_bookings%rowtype;
  v_resources jsonb;
begin
  select * into v_booking from public.vacleaner_bookings where id=p_booking_id;
  if not found then raise exception 'booking_not_found'; end if;
  if v_booking.status = 'confirmed' then return v_booking; end if;
  if v_booking.status not in ('pending','waiting_payment') then raise exception 'booking_not_pending'; end if;

  select coalesce(jsonb_agg(jsonb_build_object('resource_code',br.resource_code,'quantity',br.quantity)),'[]'::jsonb)
    into v_resources
    from public.vacleaner_booking_resources br
   where br.booking_id=p_booking_id;

  return public.vacleaner_apply_reservation(
    p_booking_id,
    v_booking.start_date,
    v_booking.return_date,
    v_booking.pickup_window,
    v_booking.return_window,
    v_booking.start_at,
    v_booking.end_at,
    v_booking.rental_days,
    v_resources,
    'confirmed',
    null
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.vacleaner_confirm_without_prepayment_v1(p_booking_id uuid, p_extras jsonb, p_customer_name text DEFAULT NULL::text, p_customer_phone text DEFAULT NULL::text)
 RETURNS vacleaner_bookings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_booking public.vacleaner_bookings%rowtype;
  v_resources jsonb;
  v_now timestamptz := pg_catalog.now();
  v_hold timestamptz := pg_catalog.now() + interval '5 minutes';
begin
  select * into v_booking
    from public.vacleaner_bookings
   where id = p_booking_id
   for update;
  if not found then raise exception 'booking_not_found'; end if;

  if v_booking.status = 'confirmed'
     and coalesce((v_booking.extras->'prepayment_waiver'->>'active')::boolean,false) then
    return v_booking;
  end if;
  if v_booking.status not in ('pending','waiting_payment') then
    raise exception 'invalid_transition';
  end if;

  select coalesce(
    jsonb_agg(jsonb_build_object('resource_code',br.resource_code,'quantity',br.quantity)),
    '[]'::jsonb
  ) into v_resources
  from public.vacleaner_booking_resources br
  where br.booking_id = p_booking_id;

  if jsonb_array_length(v_resources) < 1 then
    raise exception 'invalid_resources';
  end if;

  perform public.vacleaner_apply_reservation(
    p_booking_id,
    v_booking.start_date,
    v_booking.return_date,
    v_booking.pickup_window,
    v_booking.return_window,
    v_booking.start_at,
    v_booking.end_at,
    v_booking.rental_days,
    v_resources,
    'waiting_payment',
    v_hold
  );

  update public.vacleaner_bookings
     set status = 'confirmed',
         hold_expires_at = null,
         prepayment_paid = false,
         prepayment_amount = 0,
         prepayment_paid_at = null,
         confirmed_at = coalesce(confirmed_at,v_now),
         extras = coalesce(p_extras,extras,'{}'::jsonb),
         customer_name = coalesce(nullif(pg_catalog.btrim(p_customer_name),''),customer_name),
         customer_phone = coalesce(nullif(pg_catalog.btrim(p_customer_phone),''),customer_phone),
         updated_at = v_now
   where id = p_booking_id
   returning * into v_booking;

  return v_booking;
end;
$function$

CREATE OR REPLACE FUNCTION public.vacleaner_keep_admin_bundle_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  old_bundle jsonb;
  puzzi_jimmy_weekday numeric;
  puzzi_jimmy_weekend numeric;
  abir_weekday numeric;
  abir_weekend numeric;
begin
  if new.key <> 'catalog' then
    return new;
  end if;

  old_bundle := old.value::jsonb #> '{products,puzzi_jimmy_abir}';
  if old_bundle is null then
    return new;
  end if;

  puzzi_jimmy_weekday := coalesce((new.value::jsonb #>> '{products,puzzi_jimmy,weekday}')::numeric, 1050);
  puzzi_jimmy_weekend := coalesce((new.value::jsonb #>> '{products,puzzi_jimmy,weekend}')::numeric, 1150);
  abir_weekday := coalesce((new.value::jsonb #>> '{products,abir,weekday}')::numeric, 800);
  abir_weekend := coalesce((new.value::jsonb #>> '{products,abir,weekend}')::numeric, 900);

  old_bundle := jsonb_set(old_bundle, '{weekday}', to_jsonb((puzzi_jimmy_weekday + abir_weekday)::numeric), true);
  old_bundle := jsonb_set(old_bundle, '{weekend}', to_jsonb((puzzi_jimmy_weekend + abir_weekend)::numeric), true);
  new.value := jsonb_set(new.value::jsonb, '{products,puzzi_jimmy_abir}', old_bundle, true);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.vacleaner_log_booking_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  watched constant text[] := array[
    'status','prepayment_amount','prepayment_paid',
    'issue_payment_amount','issue_payment_paid',
    'return_payment_amount','return_payment_paid',
    'deposit_amount','deposit_paid','deposit_returned',
    'base_amount','extras_amount','delivery_amount','total_amount','extras'
  ];
  before_values jsonb := '{}'::jsonb;
  after_values jsonb := '{}'::jsonb;
  fields text[] := '{}';
  field_name text;
begin
  after_values := jsonb_build_object(
    'status', new.status,
    'prepayment_amount', new.prepayment_amount,
    'prepayment_paid', new.prepayment_paid,
    'issue_payment_amount', new.issue_payment_amount,
    'issue_payment_paid', new.issue_payment_paid,
    'return_payment_amount', new.return_payment_amount,
    'return_payment_paid', new.return_payment_paid,
    'deposit_amount', new.deposit_amount,
    'deposit_paid', new.deposit_paid,
    'deposit_returned', new.deposit_returned,
    'base_amount', new.base_amount,
    'extras_amount', new.extras_amount,
    'delivery_amount', new.delivery_amount,
    'total_amount', new.total_amount,
    'extras', new.extras
  );

  if tg_op = 'INSERT' then
    insert into public.vacleaner_booking_audit (
      booking_id, booking_code, event_type, changed_fields, old_values, new_values, source
    ) values (
      new.id, new.booking_code, 'created', watched, '{}'::jsonb, after_values, 'database'
    );
    return new;
  end if;

  before_values := jsonb_build_object(
    'status', old.status,
    'prepayment_amount', old.prepayment_amount,
    'prepayment_paid', old.prepayment_paid,
    'issue_payment_amount', old.issue_payment_amount,
    'issue_payment_paid', old.issue_payment_paid,
    'return_payment_amount', old.return_payment_amount,
    'return_payment_paid', old.return_payment_paid,
    'deposit_amount', old.deposit_amount,
    'deposit_paid', old.deposit_paid,
    'deposit_returned', old.deposit_returned,
    'base_amount', old.base_amount,
    'extras_amount', old.extras_amount,
    'delivery_amount', old.delivery_amount,
    'total_amount', old.total_amount,
    'extras', old.extras
  );

  foreach field_name in array watched loop
    if before_values -> field_name is distinct from after_values -> field_name then
      fields := array_append(fields, field_name);
    end if;
  end loop;

  if coalesce(array_length(fields, 1), 0) > 0 then
    insert into public.vacleaner_booking_audit (
      booking_id, booking_code, event_type, changed_fields, old_values, new_values, source
    ) values (
      new.id, new.booking_code, 'updated', fields, before_values, after_values, 'database'
    );
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.vacleaner_operational_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_definition text := '';
  v_lock boolean := false;
  v_half_open boolean := false;
  v_capacity_block boolean := false;
  v_pending_non_reserving boolean := false;
begin
  select pg_catalog.pg_get_functiondef(p.oid)
    into v_definition
    from pg_catalog.pg_proc p
    join pg_catalog.pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public'
     and p.proname = 'vacleaner_apply_reservation'
   order by p.oid desc
   limit 1;

  if coalesce(v_definition,'') <> '' then
    v_lock := pg_catalog.strpos(v_definition, 'pg_advisory_xact_lock') > 0;
    v_half_open := pg_catalog.strpos(v_definition, 'vacleaner_slot_index(b.return_date,b.return_window) > v_slot') > 0;
    v_capacity_block := pg_catalog.strpos(v_definition, 'v_reserved + v_resource.quantity > v_capacity') > 0
      and pg_catalog.strpos(v_definition, 'inventory_conflict') > 0;
    v_pending_non_reserving := pg_catalog.strpos(v_definition, 'p_target_status <> ''pending''') > 0;
  end if;

  return pg_catalog.jsonb_build_object(
    'authority', 'vacleaner_apply_reservation',
    'version', 1,
    'functionPresent', coalesce(v_definition,'') <> '',
    'transactionLock', v_lock,
    'halfOpenSlots', v_half_open,
    'capacityHardBlock', v_capacity_block,
    'pendingDoesNotReserve', v_pending_non_reserving,
    'healthy', v_lock and v_half_open and v_capacity_block and v_pending_non_reserving
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.vacleaner_preserve_best_promo_discount()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_promo jsonb;
  v_discount jsonb;
  v_raw integer;
  v_promo_value integer;
  v_promo_amount integer;
  v_loyalty_percent integer;
  v_loyalty_amount integer;
  v_type text;
begin
  if coalesce(current_setting('vacleaner.allow_promo_detach', true),'') = '1' then
    return new;
  end if;

  v_promo := old.extras -> 'promo';
  if coalesce(old.extras -> 'discount' ->> 'source','') <> 'promo'
     or coalesce(v_promo ->> 'applied','false') <> 'true' then
    return new;
  end if;
  if coalesce(new.extras -> 'discount' ->> 'source','') = 'manual' then
    return new;
  end if;

  v_raw := greatest(0, coalesce((new.extras ->> 'base_before_discount')::integer,(old.extras ->> 'base_before_discount')::integer,new.base_amount,0));
  v_promo_value := greatest(0, coalesce((v_promo ->> 'discount_value')::integer,0));
  v_type := coalesce(v_promo ->> 'discount_type','percent');
  v_promo_amount := least(v_raw, case when v_type='fixed' then v_promo_value else round(v_raw * least(100,v_promo_value) / 100.0)::integer end);
  v_loyalty_percent := greatest(0, least(10, coalesce((new.extras -> 'loyalty' ->> 'percent')::integer,0)));
  v_loyalty_amount := round(v_raw * v_loyalty_percent / 100.0)::integer;

  if v_promo_amount > v_loyalty_amount then
    v_discount := jsonb_build_object('source','promo','percent',case when v_type='percent' then v_promo_value else 0 end,'amount',v_promo_amount);
    new.extras := jsonb_set(jsonb_set(new.extras,'{promo}',v_promo,true),'{discount}',v_discount,true);
    new.base_amount := greatest(0,v_raw-v_promo_amount);
    new.total_amount := new.base_amount + coalesce(new.extras_amount,0) + coalesce(new.delivery_amount,0);
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.vacleaner_redeem_promo(p_promo_code_id uuid, p_campaign_id uuid, p_booking_id uuid, p_customer_phone text, p_discount_amount integer, p_base_before_discount integer)
 RETURNS vacleaner_promo_redemptions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_code public.vacleaner_promo_codes%rowtype;
  v_campaign public.vacleaner_campaigns%rowtype;
  v_total integer;
  v_customer integer;
  v_result public.vacleaner_promo_redemptions%rowtype;
begin
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext('vacleaner-promo:' || p_promo_code_id::text));
  select * into v_code from public.vacleaner_promo_codes where id=p_promo_code_id for update;
  if not found or v_code.campaign_id<>p_campaign_id or not v_code.active then raise exception 'promo_unavailable'; end if;
  select * into v_campaign from public.vacleaner_campaigns where id=p_campaign_id for update;
  if not found or v_campaign.status<>'active' then raise exception 'promo_unavailable'; end if;
  if v_campaign.starts_at>pg_catalog.now() or (v_campaign.ends_at is not null and v_campaign.ends_at<=pg_catalog.now()) then raise exception 'promo_expired'; end if;
  if v_code.expires_at is not null and v_code.expires_at<=pg_catalog.now() then raise exception 'promo_expired'; end if;
  if v_code.customer_phone is not null and v_code.customer_phone<>p_customer_phone then raise exception 'promo_customer_mismatch'; end if;

  select count(*)::integer into v_total from public.vacleaner_promo_redemptions where promo_code_id=p_promo_code_id;
  if v_total>=v_code.usage_limit then raise exception 'promo_limit_reached'; end if;
  if v_campaign.usage_limit_total is not null then
    select count(*)::integer into v_total from public.vacleaner_promo_redemptions where campaign_id=p_campaign_id;
    if v_total>=v_campaign.usage_limit_total then raise exception 'promo_limit_reached'; end if;
  end if;
  select count(*)::integer into v_customer from public.vacleaner_promo_redemptions where campaign_id=p_campaign_id and customer_phone=p_customer_phone;
  if v_customer>=v_campaign.usage_limit_per_customer then raise exception 'promo_customer_limit'; end if;

  insert into public.vacleaner_promo_redemptions(campaign_id,promo_code_id,booking_id,customer_phone,discount_amount,base_before_discount)
  values(p_campaign_id,p_promo_code_id,p_booking_id,p_customer_phone,p_discount_amount,p_base_before_discount)
  returning * into v_result;
  return v_result;
end;
$function$
